-- EnviroAI schema for Postgres (generated by scripts/export-postgres.py)

DROP TABLE IF EXISTS "ai_conversations" CASCADE;
CREATE TABLE "ai_conversations" (
  "id" text NOT NULL,
  "user_id" text NOT NULL,
  "title" text,
  "context_json" text,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  "is_shared" bigint DEFAULT 0 NOT NULL,
  "summary" text,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "ai_messages" CASCADE;
CREATE TABLE "ai_messages" (
  "id" text NOT NULL,
  "conversation_id" text NOT NULL,
  "role" text NOT NULL,
  "content" text NOT NULL,
  "citations_json" text,
  "confidence" text,
  "retrieved_chunk_ids_json" text,
  "model" text,
  "tokens_in" bigint,
  "tokens_out" bigint,
  "created_at" text NOT NULL,
  "workspace_json" text,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "answers" CASCADE;
CREATE TABLE "answers" (
  "id" text NOT NULL,
  "question_id" text NOT NULL,
  "author_id" text,
  "is_ai" bigint DEFAULT 0 NOT NULL,
  "body_en" text,
  "body_ar" text,
  "citations_json" text,
  "confidence" text,
  "is_verified" bigint DEFAULT 0 NOT NULL,
  "verified_by" text,
  "verified_at" text,
  "helpful_count" bigint DEFAULT 0 NOT NULL,
  "created_at" text NOT NULL,
  PRIMARY KEY ("id")
);

DROP TABLE IF EXISTS "api_keys" CASCADE;
CREATE TABLE "api_keys" (
  "id" text NOT NULL,
